"""Protected grading order on generated byte fixtures; no biological results.

Original panel admission and numerical evaluation are explicitly stubbed. The
production successor freeze/score, snapshot I/O, identities and policy comparison
run unchanged. No original data/target, process or model is used.
"""
import hashlib
import importlib.util
import json
from pathlib import Path
import types
import unittest

HERE = Path(__file__).resolve().parent
spec = importlib.util.spec_from_file_location('_smc_full_panel_fixture_helpers', HERE / 'test_benchmark.py')
fixtures = importlib.util.module_from_spec(spec)
spec.loader.exec_module(fixtures)


class ProtectedScoreBoundaryControls(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        fixtures.FullPanelControls.setUpClass()

    def setUp(self):
        self.f = fixtures.FullPanelControls('test_authentic_parent_task_and_selected_budget')
        self.f.setUp()
        self.api = self.f.api
        self.events = []
        self.method, self.method_sha = self.f.method()
        self.actual = self.f.root / 'actual-use.json'
        fixtures.dump(self.actual, self.f.actual(self.method_sha))
        predictions = self.f.root / 'predictions'
        predictions.mkdir()
        self.prediction = predictions / 'offline.h5'
        self.prediction.write_bytes(b'generated complete-prediction stand-in; no neural arrays')
        protected = self.f.root / 'protected'
        protected.mkdir()
        self.target = protected / 'target.h5'
        self.target.write_bytes(b'generated protected-target stand-in')
        self.evaluator = self.f.root / 'evaluation.py'
        self.evaluator.write_bytes(b'# generated evaluator identity; never executed\n')
        self.metrics = tuple(self.api.source.METRICS)
        self.values = {metric: (index + 1) / 10 for index, metric in enumerate(self.metrics)}
        original_hash = self.api.hash_file

        def tracked_hash(path, *args, **kwargs):
            if Path(path) == self.target:
                self.events.append(('target_read', str(path)))
            return original_hash(path, *args, **kwargs)

        def validate_submission(path, panel):
            self.events.append(('validate_submission', str(path)))
            self.assertTrue(Path(path).is_file())
            return None

        def evaluate(target, prediction):
            self.events.append(('evaluate', str(prediction)))
            self.assertEqual(Path(target), self.target)
            self.assertEqual(Path(prediction).read_bytes(), self.prediction.read_bytes())
            return [{'mc_maze_split': self.values.copy()}]

        self.api.hash_file = tracked_hash
        self.api.source = types.SimpleNamespace(
            TARGET_SHA256=hashlib.sha256(self.target.read_bytes()).hexdigest(),
            SCORER_SHA256=hashlib.sha256(self.evaluator.read_bytes()).hexdigest(),
            DATASET='mc_maze', METRICS=self.metrics,
            validate_submission=validate_submission,
            load_original_scorer=lambda path: types.SimpleNamespace(evaluate=evaluate))
        self.frozen = self.f.root / 'prediction-freeze.json'
        self.api.freeze(self.f.pair, self.f.pair_sha, self.f.task, fixtures.module.TASK_SHA256,
            self.f.condition, 'improvement', {'offline': self.prediction}, self.actual, self.frozen,
            max_bytes=self.f.cap, method_path=self.method, method_sha256=self.method_sha)
        self.frozen_sha = original_hash(self.frozen)
        self.report = self.f.root / 'score.json'
        self.events.clear()

    def tearDown(self):
        self.f.tearDown()

    def score(self):
        return self.api.score(self.frozen, self.frozen_sha, self.f.pair, self.f.pair_sha,
            self.f.task, fixtures.module.TASK_SHA256, self.f.pair_root / self.f.condition,
            self.target, self.evaluator, self.report, scratch_bytes=self.f.cap,
            max_bytes=self.f.cap, method_path=self.method, method_sha256=self.method_sha)

    def assert_no_target_access(self):
        self.assertFalse(any(event[0] == 'target_read' for event in self.events))
        self.assertFalse(self.report.exists())

    def test_complete_snapshot_is_validated_before_first_target_access(self):
        report = self.score()
        first_target = next(index for index, event in enumerate(self.events) if event[0] == 'target_read')
        validations = [event for event in self.events[:first_target] if event[0] == 'validate_submission']
        self.assertTrue(validations)
        self.assertNotEqual(Path(validations[-1][1]), self.prediction)
        self.assertTrue(any(event[0] == 'evaluate' for event in self.events))
        self.assertEqual(report['inference_condition_id'], fixtures.module.INFERENCE_CONDITION)
        self.assertFalse(report['execution_verified'])
        self.assertFalse(report['AI_attribution_verified'])
        self.assertFalse(report['pre_test_authoring_isolation_verified'])

    def test_mutated_prediction_is_refused_before_target_access(self):
        self.prediction.write_bytes(b'changed after result freeze')
        with self.assertRaisesRegex(ValueError, 'snapshot differs from joint prediction freeze'):
            self.score()
        self.assert_no_target_access()

    def test_mutated_program_is_refused_before_target_access(self):
        method = json.loads(self.method.read_text())
        Path(method['program']['path']).chmod(0o600)
        Path(method['program']['path']).write_bytes(b'changed after method freeze')
        with self.assertRaisesRegex(ValueError, 'frozen program/artifacts changed'):
            self.score()
        self.assert_no_target_access()

    def test_rehashed_legacy_freeze_is_refused_before_target_access(self):
        value = json.loads(self.frozen.read_text())
        value['schema'] = 'smc_continuous_frozen_v2'
        self.frozen.chmod(0o600)
        self.frozen_sha = fixtures.dump(self.frozen, value)
        with self.assertRaisesRegex(ValueError, 'stale or wrong frozen result identity'):
            self.score()
        self.assert_no_target_access()

    def test_changed_evaluator_is_refused_before_target_access(self):
        self.evaluator.write_bytes(b'# changed generated evaluator identity\n')
        with self.assertRaisesRegex(ValueError, 'wrong original evaluator'):
            self.score()
        self.assert_no_target_access()


if __name__ == '__main__':
    unittest.main()
